workflow-item.script:
// Saves through the vRO REST API so the change is committed to version history.
// The scripting API (setContentFromMimeAttachment) updates content but creates no history,
// and saveToVersionRepository() is deprecated and no longer functional.
System.getModule("in.co.cloudblogger.resource").commitResourceElementContent(resElem, content, MIME_TYPE, VERSION);
